206			return 0;
207		    } else if (header != head_buf) {
208			buf++;
209			goto payload_start;
210		    } else {
211			header[0] = header[1];
212			header[1] = header[2];
213			header[2] = header[3];
214			bytes = 3;
215			goto continue_header;
216		    }
217		}
218		if (demux_pid || demux_pes) {
219		    if (header[3] != 0xbd) {
220			fprintf (stderr, "bad stream id %x\n", header[3]);
221			exit (1);
222		    }
223		    NEEDBYTES (9);
224		    if ((header[6] & 0xc0) != 0x80) {	/* not mpeg2 */
225			fprintf (stderr, "bad multiplex - not mpeg2\n");
226			exit (1);
227		    }
228		    len = 9 + header[8];
229		    NEEDBYTES (len);
230		    DONEBYTES (len);
231		    bytes = 6 + (header[4] << 8) + header[5] - len;
232		    if (bytes > end - buf) {
233			fwrite (buf, end - buf, 1, stdout);
234			state = DEMUX_DATA;
235			state_bytes = bytes - (end - buf);
236			return 0;
237		    } else if (bytes > 0) {
238			fwrite (buf, bytes, 1, stdout);
239			buf += bytes;
240		    }
241		} else switch (header[3]) {
242		case 0xb9:	/* program end code */
243		    /* DONEBYTES (4); */
244		    /* break;         */
245		    return 1;
246		case 0xba:	/* pack header */
247		    NEEDBYTES (5);
248		    if ((header[4] & 0xc0) == 0x40) {	/* mpeg2 */
249			NEEDBYTES (14);
