251			NEEDBYTES (len);
252			DONEBYTES (len);
253			/* header points to the mpeg2 pack header */
254		    } else if ((header[4] & 0xf0) == 0x20) {	/* mpeg1 */
255			NEEDBYTES (12);
256			DONEBYTES (12);
257			/* header points to the mpeg1 pack header */
258		    } else {
