260			DONEBYTES (5);
261		    }
262		    break;
263		case 0xbd:	/* private stream 1 */
264		    NEEDBYTES (7);
265		    if ((header[6] & 0xc0) == 0x80) {	/* mpeg2 */
266			NEEDBYTES (9);
267			len = 10 + header[8];
268			NEEDBYTES (len);
269			/* header points to the mpeg2 pes header */
270		    } else {	/* mpeg1 */
271			len = 7;
272			while ((header-1)[len] == 0xff) {
273			    len++;
274			    NEEDBYTES (len);
275			    if (len == 23) {
276				fprintf (stderr, "too much stuffing\n");
277				break;
278			    }
279			}
280			if (((header-1)[len] & 0xc0) == 0x40) {
281			    len += 2;
282			    NEEDBYTES (len);
283			}
284			len += mpeg1_skip_table[(header - 1)[len] >> 4] + 1;
285			NEEDBYTES (len);
286			/* header points to the mpeg1 pes header */
287		    }
288		    if ((header-1)[len] != demux_track) {
289			DONEBYTES (len);
290			bytes = 6 + (header[4] << 8) + header[5] - len;
291			if (bytes <= 0)
292			    continue;
293			goto skip;
294		    }
295		    len += 3;
296		    NEEDBYTES (len);
297		    DONEBYTES (len);
298		    bytes = 6 + (header[4] << 8) + header[5] - len;
299		    if (bytes > end - buf) {
300			fwrite (buf, end - buf, 1, stdout);
301			state = DEMUX_DATA;
302			state_bytes = bytes - (end - buf);
303			return 0;
304		    } else if (bytes > 0) {
305			fwrite (buf, bytes, 1, stdout);
306			buf += bytes;
307		    }
308		    break;
309		default:
310		    if (header[3] < 0xb9) {
311			fprintf (stderr,
312				 "looks like a video stream, not system stream\n");
313			exit (1);
314		    } else {
315			NEEDBYTES (6);
316			DONEBYTES (6);
317			bytes = (header[4] << 8) + header[5];
318		    skip:
319			if (bytes > end - buf) {
320			    state = DEMUX_SKIP;
321			    state_bytes = bytes - (end - buf);
322			    return 0;
323			}
324			buf += bytes;
325		    }
326		}
327	    }
328	}
