330	static void ps_loop (void)
331	{
332	    uint8_t * end;
333	
334	    do {
335		end = buffer + fread (buffer, 1, BUFFER_SIZE, in_file);
336		if (demux (buffer, end, 0))
337		    break;	/* hit program_end_code */
338	    } while (end == buffer + BUFFER_SIZE);
339	}
