341	static void ts_loop (void)
342	{
343	    uint8_t * buf;
344	    uint8_t * nextbuf;
345	    uint8_t * data;
346	    uint8_t * end;
347	    int pid;
348	
349	    buf = buffer;
350	    while (1) {
351		end = buf + fread (buf, 1, buffer + BUFFER_SIZE - buf, in_file);
352		buf = buffer;
353		for (; (nextbuf = buf + 188) <= end; buf = nextbuf) {
354		    if (*buf != 0x47) {
355			fprintf (stderr, "bad sync byte\n");
356			nextbuf = buf + 1;
357			continue;
358		    }
359		    pid = ((buf[1] << 8) + buf[2]) & 0x1fff;
360		    if (pid != demux_pid)
361			continue;
362		    data = buf + 4;
363		    if (buf[3] & 0x20) {	/* buf contains an adaptation field */
364			data = buf + 5 + buf[4];
365			if (data > nextbuf)
366			    continue;
367		    }
368		    if (buf[3] & 0x10)
369			demux (data, nextbuf,
370			       (buf[1] & 0x40) ? DEMUX_PAYLOAD_START : 0);
371		}
372		if (end != buffer + BUFFER_SIZE)
373		    break;
374		memcpy (buffer, buf, end - buf);
375		buf = buffer + (end - buf);
376	    }
377	}
