81:     if (!frame_counter) {
82: 	tv_start = tv_beg = tv_end;
83: 	signal (SIGINT, signal_handler);
84:     }
85: 
86:     elapsed = (tv_end.tv_sec - tv_beg.tv_sec) * 100 +
87: 	(tv_end.tv_usec - tv_beg.tv_usec) / 10000;
88:     total_elapsed = (tv_end.tv_sec - tv_start.tv_sec) * 100 +
89: 	(tv_end.tv_usec - tv_start.tv_usec) / 10000;
90: 
91:     if (final) {
92: 	if (total_elapsed)
93: 	    tfps = frame_counter * 100.0 / total_elapsed;
94: 	else
95: 	    tfps = 0;
96: 
97: 	fprintf (stderr,"\n%d frames decoded in %.2f seconds (%.2f fps)\n",
98: 		 frame_counter, total_elapsed / 100.0, tfps);
99: 
100: 	return;
101:     }
102: 
103:     frame_counter++;
104: 
105:     if (elapsed < 50)	/* only display every 0.50 seconds */
106: 	return;
