113: 
114:     fprintf (stderr, "%d frames in %.2f sec (%.2f fps), "
115: 	     "%d last %.2f sec (%.2f fps)\n", frame_counter,
116: 	     total_elapsed / 100.0, tfps, frames, elapsed / 100.0, fps);
117: 
118:     last_count = frame_counter;
