168: 	    if (output_open == NULL) {
169: 		fprintf (stderr, "Invalid audio driver: %s\n", optarg);
170: 		print_usage (argv);
171: 	    }
172: 	    break;
173: 
174: 	case 's':
175: 	    demux_track = 0x80;
176: 	    if (optarg != NULL) {
177: 		demux_track = strtol (optarg, &s, 0);
178: 		if (demux_track < 0x80)
179: 		    demux_track += 0x80;
180: 		if (demux_track < 0x80 || demux_track > 0x87 || *s) {
181: 		    fprintf (stderr, "Invalid track number: %s\n", optarg);
182: 		    print_usage (argv);
183: 		}
184: 	    }
185: 	    break;
186: 
187: 	case 't':
188: 	    demux_pid = strtol (optarg, &s, 0);
189: 	    if (demux_pid < 0x10 || demux_pid > 0x1ffe || *s) {
190: 		fprintf (stderr, "Invalid pid: %s\n", optarg);
191: 		print_usage (argv);
192: 	    }
193: 	    break;
194: 
195: 	case 'T':
196: 	    demux_pes = 1;
197: 	    break;
198: 
199: 	case 'c':
200: 	    disable_accel = 1;
201: 	    break;
202: 
203: 	case 'r':
204: 	    disable_dynrng = 1;
205: 	    break;
206: 
207: 	case 'a':
208: 	    disable_adjust = 1;
209: 	    break;
210: 
211: 	case 'g':
212: 	    gain = strtod (optarg, &s);
213: 	    if (gain < -96 || gain > 96 || *s) {
214: 		fprintf (stderr, "Invalid gain: %s\n", optarg);
215: 		print_usage (argv);
216: 	    }
217: 	    gain = pow (2, gain / 6);
218: 	    break;
219: 
