221: 	    print_usage (argv);
222: 	}
223: 
224:     /* -o not specified, use a default driver */
225:     if (output_open == NULL)
226: 	output_open = drivers[0].open;
227: 
228:     if (optind < argc) {
229: 	in_file = fopen (argv[optind], "rb");
