239: static void a52_decode_data (uint8_t * start, uint8_t * end)
240: {
241:     static uint8_t buf[3840];
242:     static uint8_t * bufptr = buf;
243:     static uint8_t * bufpos = buf + 7;
244: 
245:     /*
246:      * sample_rate and flags are static because this routine could
247:      * exit between the a52_syncinfo() and the ao_setup(), and we want
248:      * to have the same values when we get back !
249:      */
250: 
251:     static int sample_rate;
252:     static int flags;
253:     int bit_rate;
254:     int len;
255: 
256:     while (1) {
257: 	len = end - start;
258: 	if (!len)
259: 	    break;
260: 	if (len > bufpos - bufptr)
261: 	    len = bufpos - bufptr;
262: 	memcpy (bufptr, start, len);
263: 	bufptr += len;
264: 	start += len;
265: 	if (bufptr == bufpos) {
266: 	    if (bufpos == buf + 7) {
267: 		int length;
268: 
269: 		length = a52_syncinfo (buf, &flags, &sample_rate, &bit_rate);
270: 
271:                 /* treat crc failure as sync failure - could be cleaner */
272: 		if (!length) {
273: 		    fprintf (stderr, "skip\n");
274: 		    for (bufptr = buf; bufptr < buf + 6; bufptr++)
275: 			bufptr[0] = bufptr[1];
276: 		    continue;
277: 		}
278: 		bufpos = buf + length;
279: 	    } else {
280: 		level_t level;
281: 		sample_t bias;
282: 		int i;
283: 
284:                 int length;
285: 
286:                 length = a52_syncinfo (buf, &flags, &sample_rate, &bit_rate);
287:                 if (a52_crc (buf, length))
288:                     goto error;
289: 
290: 		if (output->setup (output, sample_rate, &flags, &level, &bias))
291: 		    goto error;
292: 		if (!disable_adjust)
293: 		    flags |= A52_ADJUST_LEVEL;
294: 		level = (level_t) (level * gain);
295: 		if (a52_frame (state, buf, &flags, &level, bias))
296: 		    goto error;
297: 		if (disable_dynrng)
298: 		    a52_dynrng (state, NULL, NULL);
299: 		for (i = 0; i < 6; i++) {
300: 		    if (a52_block (state))
301: 			goto error;
302: 		    if (output->play (output, flags, a52_samples (state)))
303: 			goto error;
304: 		}
305: 		bufptr = buf;
306: 		bufpos = buf + 7;
307: 		print_fps (0);
308: 		continue;
309: 	    error:
310: 		fprintf (stderr, "error\n");
311: 		bufptr = buf;
312: 		bufpos = buf + 7;
313: 	    }
314: 	}
315:     }
316: }
