548: static void ps_loop (void)
549: {
550:     uint8_t * end;
551: 
552:     do {
553: 	end = buffer + fread (buffer, 1, BUFFER_SIZE, in_file);
554: 	if (demux (buffer, end, 0))
555: 	    break;	/* hit program_end_code */
556:     } while (end == buffer + BUFFER_SIZE && !sigint);
557: }
