559: static void ts_loop (void)
560: {
561:     uint8_t * buf;
562:     uint8_t * nextbuf;
563:     uint8_t * data;
564:     uint8_t * end;
565:     int pid;
566: 
567:     buf = buffer;
568:     do {
569: 	end = buf + fread (buf, 1, buffer + BUFFER_SIZE - buf, in_file);
570: 	buf = buffer;
571: 	for (; (nextbuf = buf + 188) <= end; buf = nextbuf) {
572: 	    if (*buf != 0x47) {
573: 		fprintf (stderr, "bad sync byte\n");
574: 		nextbuf = buf + 1;
575: 		continue;
576: 	    }
577: 	    pid = ((buf[1] << 8) + buf[2]) & 0x1fff;
578: 	    if (pid != demux_pid)
579: 		continue;
580: 	    data = buf + 4;
581: 	    if (buf[3] & 0x20) {	/* buf contains an adaptation field */
582: 		data = buf + 5 + buf[4];
583: 		if (data > nextbuf)
584: 		    continue;
585: 	    }
586: 	    if (buf[3] & 0x10)
587: 		demux (data, nextbuf,
588: 		       (buf[1] & 0x40) ? DEMUX_PAYLOAD_START : 0);
589: 	}
590: 	if (end != buffer + BUFFER_SIZE)
591: 	    break;
592: 	memcpy (buffer, buf, end - buf);
593: 	buf = buffer + (end - buf);
594:     } while (!sigint);
595: }
