597: static void es_loop (void)
598: {
599:     int size;
600: 		
601:     do {
602: 	size = fread (buffer, 1, BUFFER_SIZE, in_file);
603: 	a52_decode_data (buffer, buffer + size);
604:     } while (size == BUFFER_SIZE && !sigint);
605: }
