99: 		  int * sample_rate, int * bit_rate)
100: {
101:     static int rate[] = { 32,  40,  48,  56,  64,  80,  96, 112,
102: 			 128, 160, 192, 224, 256, 320, 384, 448,
103: 			 512, 576, 640};
104:     static uint8_t lfeon[8] = {0x10, 0x10, 0x04, 0x04, 0x04, 0x01, 0x04, 0x01};
105:     int frmsizecod;
106:     int bitrate;
107:     int half;
108:     int acmod;
109: 
110:     if ((buf[0] != 0x0b) || (buf[1] != 0x77))	/* syncword */
111: 	return 0;
112: 
113:     if (buf[5] >= 0x60)		/* bsid >= 12 */
114: 	return 0;
115:     half = halfrate[buf[5] >> 3];
116: 
117:     /* acmod, dsurmod and lfeon */
118:     acmod = buf[6] >> 5;
119:     *flags = ((((buf[6] & 0xf8) == 0x50) ? A52_DOLBY : acmod) |
120: 	      ((buf[6] & lfeon[acmod]) ? A52_LFE : 0));
121: 
122:     frmsizecod = buf[4] & 63;
123:     if (frmsizecod >= 38)
124: 	return 0;
125:     bitrate = rate [frmsizecod >> 1];
126:     *bit_rate = (bitrate * 1000) >> half;
127: 
128:     switch (buf[4] & 0xc0) {
129:     case 0:
130: 	*sample_rate = 48000 >> half;
131: 	return 4 * bitrate;
132:     case 0x40:
133: 	*sample_rate = 44100 >> half;
134: 	return 2 * (320 * bitrate / 147 + (frmsizecod & 1));
135:     case 0x80:
136: 	*sample_rate = 32000 >> half;
137: 	return 6 * bitrate;
138:     default:
139: 	return 0;
140:     }
141: }
