188:     *flags = state->output;
189:     /* the 2* compensates for differences in imdct */
190:     state->dynrng = state->level = MUL_C (*level, 2);
191:     state->bias = bias;
192:     state->dynrnge = 1;
193:     state->dynrngcall = NULL;
194:     state->cplba.deltbae = DELTA_BIT_NONE;
195:     state->ba[0].deltbae = state->ba[1].deltbae = state->ba[2].deltbae =
196: 	state->ba[3].deltbae = state->ba[4].deltbae = DELTA_BIT_NONE;
197: 
198:     chaninfo = !acmod;
199:     do {
200: 	bitstream_get (state, 5);	/* dialnorm */
201: 	if (bitstream_get (state, 1))	/* compre */
202: 	    bitstream_get (state, 8);	/* compr */
203: 	if (bitstream_get (state, 1))	/* langcode */
204: 	    bitstream_get (state, 8);	/* langcod */
205: 	if (bitstream_get (state, 1))	/* audprodie */
206: 	    bitstream_get (state, 7);	/* mixlevel + roomtyp */
207:     } while (chaninfo--);
208: 
209:     bitstream_get (state, 2);		/* copyrightb + origbs */
210: 
211:     if (bitstream_get (state, 1))	/* timecod1e */
212: 	bitstream_get (state, 14);	/* timecod1 */
213:     if (bitstream_get (state, 1))	/* timecod2e */
214: 	bitstream_get (state, 14);	/* timecod2 */
215: 
216:     if (bitstream_get (state, 1)) {	/* addbsie */
217: 	int addbsil;
218: 
219: 	addbsil = bitstream_get (state, 6);
220: 	do {
221: 	    bitstream_get (state, 8);	/* addbsi */
222: 	} while (addbsil--);
223:     }
224: 
225:     return 0;
226: }
