239: static int parse_exponents (a52_state_t * state, int expstr, int ngrps,
240: 			    uint8_t exponent, uint8_t * dest)
241: {
242:     int exps;
243: 
244:     while (ngrps--) {
245: 	exps = bitstream_get (state, 7);
246: 
247: 	exponent += exp_1[exps];
248: 	if (exponent > 24)
249: 	    return 1;
250: 
251: 	switch (expstr) {
252: 	case EXP_D45:
253: 	    *(dest++) = exponent;
254: 	    *(dest++) = exponent;
255: 	case EXP_D25:
256: 	    *(dest++) = exponent;
257: 	case EXP_D15:
258: 	    *(dest++) = exponent;
259: 	}
260: 
261: 	exponent += exp_2[exps];
262: 	if (exponent > 24)
263: 	    return 1;
264: 
265: 	switch (expstr) {
266: 	case EXP_D45:
267: 	    *(dest++) = exponent;
268: 	    *(dest++) = exponent;
269: 	case EXP_D25:
270: 	    *(dest++) = exponent;
271: 	case EXP_D15:
272: 	    *(dest++) = exponent;
273: 	}
274: 
275: 	exponent += exp_3[exps];
276: 	if (exponent > 24)
277: 	    return 1;
278: 
279: 	switch (expstr) {
280: 	case EXP_D45:
281: 	    *(dest++) = exponent;
282: 	    *(dest++) = exponent;
283: 	case EXP_D25:
284: 	    *(dest++) = exponent;
285: 	case EXP_D15:
286: 	    *(dest++) = exponent;
287: 	}
288:     }	
289: 
290:     return 0;
291: }
