293: static int parse_deltba (a52_state_t * state, int8_t * deltba)
294: {
295:     int deltnseg, deltlen, delta, j;
296: 
297:     memset (deltba, 0, 50);
298: 
299:     deltnseg = bitstream_get (state, 3);
300:     j = 0;
301:     do {
302: 	j += bitstream_get (state, 5);
303: 	deltlen = bitstream_get (state, 4);
304: 	delta = bitstream_get (state, 3);
305: 	delta -= (delta >= 4) ? 3 : 4;
306: 	if (!deltlen)
307: 	    continue;
308: 	if (j + deltlen >= 50)
309: 	    return 1;
310: 	while (deltlen--)
311: 	    deltba[j++] = delta;
312:     } while (deltnseg--);
313: 
314:     return 0;
315: }
