317: static inline int zero_snr_offsets (int nfchans, a52_state_t * state)
318: {
319:     int i;
320: 
321:     if ((state->csnroffst) ||
322: 	(state->chincpl && state->cplba.bai >> 3) ||	/* cplinu, fsnroffst */
323: 	(state->lfeon && state->lfeba.bai >> 3))	/* fsnroffst */
324: 	return 0;
325:     for (i = 0; i < nfchans; i++)
326: 	if (state->ba[i].bai >> 3)			/* fsnroffst */
327: 	    return 0;
328:     return 1;
329: }
