331: static inline int16_t dither_gen (a52_state_t * state)
332: {
333:     int16_t nstate;
334: 
335:     nstate = dither_lut[state->lfsr_state >> 8] ^ (state->lfsr_state << 8);
336: 	
337:     state->lfsr_state = (uint16_t) nstate;
338: 
339:     return (3 * nstate) >> 2;
340: }
