342: #ifndef LIBA52_FIXED
343: #define COEFF(c,t,l,s,e) (c) = (t) * (s)[e]
344: #else
345: #define COEFF(c,_t,_l,s,e) do {					\
346:     quantizer_t t = (_t);					\
347:     level_t l = (_l);						\
348:     int shift = e - 5;						\
349:     sample_t tmp = t * (l >> 16) + ((t * (l & 0xffff)) >> 16);	\
350:     if (shift >= 0)						\
351: 	(c) = tmp >> shift;					\
352:     else							\
353: 	(c) = tmp << -shift;					\
354: } while (0)
355: #endif
