357: static void coeff_get (a52_state_t * state, sample_t * coeff,
358: 		       expbap_t * expbap, quantizer_set_t * quant,
359: 		       level_t level, int dither, int end)
360: {
361:     int i;
362:     uint8_t * exp;
363:     int8_t * bap;
364: 
365: #ifndef LIBA52_FIXED
366:     sample_t factor[25];
367: 
368:     for (i = 0; i <= 24; i++)
369: 	factor[i] = scale_factor[i] * level;
370: #endif
371: 
372:     exp = expbap->exp;
373:     bap = expbap->bap;
374: 
375:     for (i = 0; i < end; i++) {
376: 	int bapi;
377: 
378: 	bapi = bap[i];
379: 	switch (bapi) {
380: 	case 0:
381: 	    if (dither) {
382: 		COEFF (coeff[i], dither_gen (state), level, factor, exp[i]);
383: 		continue;
384: 	    } else {
385: 		coeff[i] = 0;
386: 		continue;
387: 	    }
388: 
389: 	case -1:
390: 	    if (quant->q1_ptr >= 0) {
391: 		COEFF (coeff[i], quant->q1[quant->q1_ptr--], level,
392: 		       factor, exp[i]);
393: 		continue;
394: 	    } else {
395: 		int code;
396: 
397: 		code = bitstream_get (state, 5);
398: 
399: 		quant->q1_ptr = 1;
400: 		quant->q1[0] = q_1_2[code];
401: 		quant->q1[1] = q_1_1[code];
402: 		COEFF (coeff[i], q_1_0[code], level, factor, exp[i]);
403: 		continue;
404: 	    }
405: 
406: 	case -2:
407: 	    if (quant->q2_ptr >= 0) {
408: 		COEFF (coeff[i], quant->q2[quant->q2_ptr--], level,
409: 		       factor, exp[i]);
410: 		continue;
411: 	    } else {
412: 		int code;
413: 
414: 		code = bitstream_get (state, 7);
415: 
416: 		quant->q2_ptr = 1;
417: 		quant->q2[0] = q_2_2[code];
418: 		quant->q2[1] = q_2_1[code];
419: 		COEFF (coeff[i], q_2_0[code], level, factor, exp[i]);
420: 		continue;
421: 	    }
422: 
423: 	case 3:
424: 	    COEFF (coeff[i], q_3[bitstream_get (state, 3)], level,
425: 		   factor, exp[i]);
426: 	    continue;
427: 
428: 	case -3:
429: 	    if (quant->q4_ptr == 0) {
430: 		quant->q4_ptr = -1;
431: 		COEFF (coeff[i], quant->q4, level, factor, exp[i]);
432: 		continue;
433: 	    } else {
434: 		int code;
435: 
436: 		code = bitstream_get (state, 7);
437: 
438: 		quant->q4_ptr = 0;
439: 		quant->q4 = q_4_1[code];
440: 		COEFF (coeff[i], q_4_0[code], level, factor, exp[i]);
441: 		continue;
442: 	    }
443: 
444: 	case 4:
445: 	    COEFF (coeff[i], q_5[bitstream_get (state, 4)], level,
446: 		   factor, exp[i]);
447: 	    continue;
448: 
449: 	default:
450: 	    COEFF (coeff[i], bitstream_get_2 (state, bapi) << (16 - bapi),
451: 		   level, factor, exp[i]);
452: 	}
453:     }
454: }
