456: static void coeff_get_coupling (a52_state_t * state, int nfchans,
457: 				level_t * coeff, sample_t (* samples)[256],
458: 				quantizer_set_t * quant, uint8_t dithflag[5])
459: {
460:     int cplbndstrc, bnd, i, i_end, ch;
461:     uint8_t * exp;
462:     int8_t * bap;
463:     level_t cplco[5];
464: 
465:     exp = state->cpl_expbap.exp;
466:     bap = state->cpl_expbap.bap;
467:     bnd = 0;
468:     cplbndstrc = state->cplbndstrc;
469:     i = state->cplstrtmant;
470:     while (i < state->cplendmant) {
471: 	i_end = i + 12;
472: 	while (cplbndstrc & 1) {
473: 	    cplbndstrc >>= 1;
474: 	    i_end += 12;
475: 	}
476: 	cplbndstrc >>= 1;
477: 	for (ch = 0; ch < nfchans; ch++)
478: 	    cplco[ch] = MUL_L (state->cplco[ch][bnd], coeff[ch]);
479: 	bnd++;
480: 
481: 	while (i < i_end) {
482: 	    quantizer_t cplcoeff;
483: 	    int bapi;
484: 
485: 	    bapi = bap[i];
486: 	    switch (bapi) {
487: 	    case 0:
488: 		for (ch = 0; ch < nfchans; ch++)
489: 		    if ((state->chincpl >> ch) & 1) {
490: 			if (dithflag[ch])
491: #ifndef LIBA52_FIXED
492: 			    samples[ch][i] = (scale_factor[exp[i]] *
493: 					      cplco[ch] * dither_gen (state));
494: #else
495: 			    COEFF (samples[ch][i], dither_gen (state),
496: 				   cplco[ch], scale_factor, exp[i]);
497: #endif
498: 			else
499: 			    samples[ch][i] = 0;
500: 		    }
501: 		i++;
502: 		continue;
503: 
504: 	    case -1:
505: 		if (quant->q1_ptr >= 0) {
506: 		    cplcoeff = quant->q1[quant->q1_ptr--];
507: 		    break;
508: 		} else {
509: 		    int code;
510: 
511: 		    code = bitstream_get (state, 5);
512: 
513: 		    quant->q1_ptr = 1;
514: 		    quant->q1[0] = q_1_2[code];
515: 		    quant->q1[1] = q_1_1[code];
516: 		    cplcoeff = q_1_0[code];
517: 		    break;
518: 		}
519: 
520: 	    case -2:
521: 		if (quant->q2_ptr >= 0) {
522: 		    cplcoeff = quant->q2[quant->q2_ptr--];
523: 		    break;
524: 		} else {
525: 		    int code;
526: 
527: 		    code = bitstream_get (state, 7);
528: 
529: 		    quant->q2_ptr = 1;
530: 		    quant->q2[0] = q_2_2[code];
531: 		    quant->q2[1] = q_2_1[code];
532: 		    cplcoeff = q_2_0[code];
533: 		    break;
534: 		}
535: 
536: 	    case 3:
537: 		cplcoeff = q_3[bitstream_get (state, 3)];
538: 		break;
539: 
540: 	    case -3:
541: 		if (quant->q4_ptr == 0) {
542: 		    quant->q4_ptr = -1;
543: 		    cplcoeff = quant->q4;
544: 		    break;
545: 		} else {
546: 		    int code;
547: 
548: 		    code = bitstream_get (state, 7);
549: 
550: 		    quant->q4_ptr = 0;
551: 		    quant->q4 = q_4_1[code];
552: 		    cplcoeff = q_4_0[code];
553: 		    break;
554: 		}
555: 
556: 	    case 4:
557: 		cplcoeff = q_5[bitstream_get (state, 4)];
558: 		break;
559: 
560: 	    default:
561: 		cplcoeff = bitstream_get_2 (state, bapi) << (16 - bapi);
562: 	    }
563: #ifndef LIBA52_FIXED
564: 	    cplcoeff *= scale_factor[exp[i]];
565: #endif
566: 	    for (ch = 0; ch < nfchans; ch++)
567: 	       if ((state->chincpl >> ch) & 1)
568: #ifndef LIBA52_FIXED
569: 		    samples[ch][i] = cplcoeff * cplco[ch];
570: #else
571: 		    COEFF (samples[ch][i], cplcoeff, cplco[ch],
572: 			   scale_factor, exp[i]);
573: #endif
574: 	    i++;
575: 	}
576:     }
577: }
