579: int a52_block (a52_state_t * state)
580: {
581:     static const uint8_t nfchans_tbl[] = {2, 1, 2, 3, 3, 4, 4, 5, 1, 1, 2};
582:     static int rematrix_band[4] = {25, 37, 61, 253};
583:     int i, nfchans, chaninfo;
584:     uint8_t cplexpstr, chexpstr[5], lfeexpstr, do_bit_alloc, done_cpl;
585:     uint8_t blksw[5], dithflag[5];
586:     level_t coeff[5];
587:     int chanbias;
588:     quantizer_set_t quant;
589:     sample_t * samples;
590: 
591:     nfchans = nfchans_tbl[state->acmod];
592: 
593:     for (i = 0; i < nfchans; i++)
594: 	blksw[i] = bitstream_get (state, 1);
595: 
596:     for (i = 0; i < nfchans; i++)
597: 	dithflag[i] = bitstream_get (state, 1);
598: 
599:     chaninfo = !state->acmod;
600:     do {
601: 	if (bitstream_get (state, 1)) {	/* dynrnge */
602: 	    int dynrng;
603: 
604: 	    dynrng = bitstream_get_2 (state, 8);
605: 	    if (state->dynrnge) {
606: 		level_t range;
607: 
608: #if !defined(LIBA52_FIXED)
609: 		range = ((((dynrng & 0x1f) | 0x20) << 13) *
610: 			 scale_factor[3 - (dynrng >> 5)]);
611: #else
612: 		range = ((dynrng & 0x1f) | 0x20) << (21 + (dynrng >> 5));
613: #endif
614: 		if (state->dynrngcall)
615: 		    range = state->dynrngcall (range, state->dynrngdata);
616: 		state->dynrng = MUL_L (state->level, range);
617: 	    }
618: 	}
619:     } while (chaninfo--);
620: 
621:     if (bitstream_get (state, 1)) {	/* cplstre */
622: 	state->chincpl = 0;
623: 	if (bitstream_get (state, 1)) {	/* cplinu */
624: 	    static uint8_t bndtab[16] = {31, 35, 37, 39, 41, 42, 43, 44,
625: 					 45, 45, 46, 46, 47, 47, 48, 48};
626: 	    int cplbegf;
627: 	    int cplendf;
628: 	    int ncplsubnd;
629: 
630: 	    for (i = 0; i < nfchans; i++)
631: 		state->chincpl |= bitstream_get (state, 1) << i;
632: 	    switch (state->acmod) {
633: 	    case 0: case 1:
634: 		return 1;
635: 	    case 2:
636: 		state->phsflginu = bitstream_get (state, 1);
637: 	    }
638: 	    cplbegf = bitstream_get (state, 4);
639: 	    cplendf = bitstream_get (state, 4);
640: 
641: 	    if (cplendf + 3 - cplbegf < 0)
642: 		return 1;
643: 	    state->ncplbnd = ncplsubnd = cplendf + 3 - cplbegf;
644: 	    state->cplstrtbnd = bndtab[cplbegf];
645: 	    state->cplstrtmant = cplbegf * 12 + 37;
646: 	    state->cplendmant = cplendf * 12 + 73;
647: 
648: 	    state->cplbndstrc = 0;
649: 	    for (i = 0; i < ncplsubnd - 1; i++)
650: 		if (bitstream_get (state, 1)) {
651: 		    state->cplbndstrc |= 1 << i;
652: 		    state->ncplbnd--;
653: 		}
654: 	}
655:     }
656: 
657:     if (state->chincpl) {	/* cplinu */
658: 	int j, cplcoe;
659: 
660: 	cplcoe = 0;
661: 	for (i = 0; i < nfchans; i++)
662: 	    if ((state->chincpl) >> i & 1)
663: 		if (bitstream_get (state, 1)) {	/* cplcoe */
664: 		    int mstrcplco, cplcoexp, cplcomant;
665: 
666: 		    cplcoe = 1;
667: 		    mstrcplco = 3 * bitstream_get (state, 2);
668: 		    for (j = 0; j < state->ncplbnd; j++) {
669: 			cplcoexp = bitstream_get (state, 4);
670: 			cplcomant = bitstream_get (state, 4);
671: 			if (cplcoexp == 15)
672: 			    cplcomant <<= 14;
673: 			else
674: 			    cplcomant = (cplcomant | 0x10) << 13;
675: #ifndef LIBA52_FIXED
676: 			state->cplco[i][j] =
677: 			    cplcomant * scale_factor[cplcoexp + mstrcplco];
678: #else
679: 			state->cplco[i][j] = (cplcomant << 11) >> (cplcoexp + mstrcplco);
680: #endif
681: 
682: 		    }
683: 		}
684: 	if ((state->acmod == 2) && state->phsflginu && cplcoe)
685: 	    for (j = 0; j < state->ncplbnd; j++)
686: 		if (bitstream_get (state, 1))	/* phsflg */
687: 		    state->cplco[1][j] = -state->cplco[1][j];
688:     }
689: 
690:     if ((state->acmod == 2) && (bitstream_get (state, 1))) {	/* rematstr */
691: 	int end;
692: 
693: 	state->rematflg = 0;
694: 	end = (state->chincpl) ? state->cplstrtmant : 253;	/* cplinu */
695: 	i = 0;
696: 	do
697: 	    state->rematflg |= bitstream_get (state, 1) << i;
698: 	while (rematrix_band[i++] < end);
699:     }
700: 
701:     cplexpstr = EXP_REUSE;
702:     lfeexpstr = EXP_REUSE;
703:     if (state->chincpl)	/* cplinu */
704: 	cplexpstr = bitstream_get (state, 2);
705:     for (i = 0; i < nfchans; i++)
706: 	chexpstr[i] = bitstream_get (state, 2);
707:     if (state->lfeon) 
708: 	lfeexpstr = bitstream_get (state, 1);
709: 
710:     for (i = 0; i < nfchans; i++)
711: 	if (chexpstr[i] != EXP_REUSE) {
712: 	    if ((state->chincpl >> i) & 1)
713: 		state->endmant[i] = state->cplstrtmant;
714: 	    else {
715: 		int chbwcod;
716: 
717: 		chbwcod = bitstream_get (state, 6);
718: 		if (chbwcod > 60)
719: 		    return 1;
720: 		state->endmant[i] = chbwcod * 3 + 73;
721: 	    }
722: 	}
723: 
724:     do_bit_alloc = 0;
725: 
726:     if (cplexpstr != EXP_REUSE) {
727: 	int cplabsexp, ncplgrps;
728: 
729: 	do_bit_alloc = 64;
730: 	ncplgrps = ((state->cplendmant - state->cplstrtmant) /
731: 		    (3 << (cplexpstr - 1)));
732: 	cplabsexp = bitstream_get (state, 4) << 1;
733: 	if (parse_exponents (state, cplexpstr, ncplgrps, cplabsexp,
734: 			     state->cpl_expbap.exp + state->cplstrtmant))
735: 	    return 1;
736:     }
737:     for (i = 0; i < nfchans; i++)
738: 	if (chexpstr[i] != EXP_REUSE) {
739: 	    int grp_size, nchgrps;
740: 
741: 	    do_bit_alloc |= 1 << i;
742: 	    grp_size = 3 << (chexpstr[i] - 1);
743: 	    nchgrps = (state->endmant[i] + grp_size - 4) / grp_size;
744: 	    state->fbw_expbap[i].exp[0] = bitstream_get (state, 4);
745: 	    if (parse_exponents (state, chexpstr[i], nchgrps,
746: 				 state->fbw_expbap[i].exp[0],
747: 				 state->fbw_expbap[i].exp + 1))
748: 		return 1;
749: 	    bitstream_get (state, 2);	/* gainrng */
750: 	}
751:     if (lfeexpstr != EXP_REUSE) {
752: 	do_bit_alloc |= 32;
753: 	state->lfe_expbap.exp[0] = bitstream_get (state, 4);
754: 	if (parse_exponents (state, lfeexpstr, 2, state->lfe_expbap.exp[0],
755: 			     state->lfe_expbap.exp + 1))
756: 	    return 1;
757:     }
758: 
759:     if (bitstream_get (state, 1)) {	/* baie */
760: 	do_bit_alloc = 127;
761: 	state->bai = bitstream_get (state, 11);
762:     }
763:     if (bitstream_get (state, 1)) {	/* snroffste */
764: 	do_bit_alloc = 127;
765: 	state->csnroffst = bitstream_get (state, 6);
766: 	if (state->chincpl)	/* cplinu */
767: 	    state->cplba.bai = bitstream_get (state, 7);
768: 	for (i = 0; i < nfchans; i++)
769: 	    state->ba[i].bai = bitstream_get (state, 7);
770: 	if (state->lfeon)
771: 	    state->lfeba.bai = bitstream_get (state, 7);
772:     }
773:     if ((state->chincpl) && (bitstream_get (state, 1))) { /* cplleake */
774: 	do_bit_alloc |= 64;
775: 	state->cplfleak = 9 - bitstream_get (state, 3);
776: 	state->cplsleak = 9 - bitstream_get (state, 3);
777:     }
778: 
779:     if (bitstream_get (state, 1)) {	/* deltbaie */
780: 	do_bit_alloc = 127;
781: 	if (state->chincpl)	/* cplinu */
782: 	    state->cplba.deltbae = bitstream_get (state, 2);
783: 	for (i = 0; i < nfchans; i++)
784: 	    state->ba[i].deltbae = bitstream_get (state, 2);
785: 	if (state->chincpl &&	/* cplinu */
786: 	    (state->cplba.deltbae == DELTA_BIT_NEW) &&
787: 	    parse_deltba (state, state->cplba.deltba))
788: 	    return 1;
789: 	for (i = 0; i < nfchans; i++)
790: 	    if ((state->ba[i].deltbae == DELTA_BIT_NEW) &&
791: 		parse_deltba (state, state->ba[i].deltba))
792: 		return 1;
793:     }
794: 
795:     if (do_bit_alloc) {
796: 	if (zero_snr_offsets (nfchans, state)) {
797: 	    memset (state->cpl_expbap.bap, 0, sizeof (state->cpl_expbap.bap));
798: 	    for (i = 0; i < nfchans; i++)
799: 		memset (state->fbw_expbap[i].bap, 0,
800: 			sizeof (state->fbw_expbap[i].bap));
801: 	    memset (state->lfe_expbap.bap, 0, sizeof (state->lfe_expbap.bap));
802: 	} else {
803: 	    if (state->chincpl && (do_bit_alloc & 64))	/* cplinu */
804: 		a52_bit_allocate (state, &state->cplba, state->cplstrtbnd,
805: 				  state->cplstrtmant, state->cplendmant,
806: 				  state->cplfleak << 8, state->cplsleak << 8,
807: 				  &state->cpl_expbap);
808: 	    for (i = 0; i < nfchans; i++)
809: 		if (do_bit_alloc & (1 << i))
810: 		    a52_bit_allocate (state, state->ba + i, 0, 0,
811: 				      state->endmant[i], 0, 0,
812: 				      state->fbw_expbap +i);
813: 	    if (state->lfeon && (do_bit_alloc & 32)) {
814: 		state->lfeba.deltbae = DELTA_BIT_NONE;
815: 		a52_bit_allocate (state, &state->lfeba, 0, 0, 7, 0, 0,
816: 				  &state->lfe_expbap);
817: 	    }
818: 	}
819:     }
820: 
821:     if (bitstream_get (state, 1)) {	/* skiple */
822: 	i = bitstream_get (state, 9);	/* skipl */
823: 	while (i--)
824: 	    bitstream_get (state, 8);
825:     }
826: 
827:     samples = state->samples;
828:     if (state->output & A52_LFE)
829: 	samples += 256;	/* shift for LFE channel */
830: 
831:     chanbias = a52_downmix_coeff (coeff, state->acmod, state->output,
832: 				  state->dynrng, state->clev, state->slev);
833: 
834:     quant.q1_ptr = quant.q2_ptr = quant.q4_ptr = -1;
835:     done_cpl = 0;
836: 
837:     for (i = 0; i < nfchans; i++) {
838: 	int j;
839: 
840: 	coeff_get (state, samples + 256 * i, state->fbw_expbap +i, &quant,
841: 		   coeff[i], dithflag[i], state->endmant[i]);
842: 
843: 	if ((state->chincpl >> i) & 1) {
844: 	    if (!done_cpl) {
845: 		done_cpl = 1;
846: 		coeff_get_coupling (state, nfchans, coeff,
847: 				    (sample_t (*)[256])samples, &quant,
848: 				    dithflag);
849: 	    }
850: 	    j = state->cplendmant;
851: 	} else
852: 	    j = state->endmant[i];
853: 	do
854: 	    (samples + 256 * i)[j] = 0;
855: 	while (++j < 256);
856:     }
857: 
858:     if (state->acmod == 2) {
859: 	int j, end, band, rematflg;
860: 
861: 	end = ((state->endmant[0] < state->endmant[1]) ?
862: 	       state->endmant[0] : state->endmant[1]);
863: 
864: 	i = 0;
865: 	j = 13;
866: 	rematflg = state->rematflg;
867: 	do {
868: 	    if (! (rematflg & 1)) {
869: 		rematflg >>= 1;
870: 		j = rematrix_band[i++];
871: 		continue;
872: 	    }
873: 	    rematflg >>= 1;
874: 	    band = rematrix_band[i++];
875: 	    if (band > end)
876: 		band = end;
877: 	    do {
878: 		sample_t tmp0, tmp1;
879: 
880: 		tmp0 = samples[j];
881: 		tmp1 = (samples+256)[j];
882: 		samples[j] = tmp0 + tmp1;
883: 		(samples+256)[j] = tmp0 - tmp1;
884: 	    } while (++j < band);
885: 	} while (j < end);
886:     }
887: 
888:     if (state->lfeon) {
889: 	if (state->output & A52_LFE) {
890: 	    coeff_get (state, samples - 256, &state->lfe_expbap, &quant,
891: 		       state->dynrng, 0, 7);
892: 	    for (i = 7; i < 256; i++)
893: 		(samples-256)[i] = 0;
894: 	    a52_imdct_512 (samples - 256, samples + 1536 - 256, state->bias);
895: 	} else {
896: 	    /* just skip the LFE coefficients */
897: 	    coeff_get (state, samples + 1280, &state->lfe_expbap, &quant,
898: 		       0, 0, 7);
899: 	}
900:     }
901: 
902:     i = 0;
903:     if (nfchans_tbl[state->output & A52_CHANNEL_MASK] < nfchans)
904: 	for (i = 1; i < nfchans; i++)
905: 	    if (blksw[i] != blksw[0])
906: 		break;
907: 
908:     if (i < nfchans) {
909: 	if (state->downmixed) {
910: 	    state->downmixed = 0;
911: 	    a52_upmix (samples + 1536, state->acmod, state->output);
912: 	}
913: 
914: 	for (i = 0; i < nfchans; i++) {
915: 	    sample_t bias;
916: 
917: 	    bias = 0;
918: 	    if (!(chanbias & (1 << i)))
919: 		bias = state->bias;
920: 
921: 	    if (coeff[i]) {
922: 		if (blksw[i])
923: 		    a52_imdct_256 (samples + 256 * i, samples + 1536 + 256 * i,
924: 				   bias);
925: 		else 
926: 		    a52_imdct_512 (samples + 256 * i, samples + 1536 + 256 * i,
927: 				   bias);
928: 	    } else {
929: 		int j;
930: 
931: 		for (j = 0; j < 256; j++)
932: 		    (samples + 256 * i)[j] = bias;
933: 	    }
934: 	}
935: 
936: 	a52_downmix (samples, state->acmod, state->output, state->bias,
937: 		     state->clev, state->slev);
938:     } else {
939: 	nfchans = nfchans_tbl[state->output & A52_CHANNEL_MASK];
940: 
941: 	a52_downmix (samples, state->acmod, state->output, 0,
942: 		     state->clev, state->slev);
943: 
944: 	if (!state->downmixed) {
945: 	    state->downmixed = 1;
946: 	    a52_downmix (samples + 1536, state->acmod, state->output, 0,
947: 			 state->clev, state->slev);
948: 	}
949: 
950: 	if (blksw[0])
951: 	    for (i = 0; i < nfchans; i++)
952: 		a52_imdct_256 (samples + 256 * i, samples + 1536 + 256 * i,
953: 			       state->bias);
954: 	else 
955: 	    for (i = 0; i < nfchans; i++)
956: 		a52_imdct_512 (samples + 256 * i, samples + 1536 + 256 * i,
957: 			       state->bias);
958:     }
959: 
960:     return 0;
961: }
962: 
963: void a52_free (a52_state_t * state)
964: {
965:     free (state->samples);
966:     free (state);
