	accel |= no_mvi ? A52_ACCEL_ALPHA : (A52_ACCEL_ALPHA |
					       A52_ACCEL_ALPHA_MVI);
    }
#endif /* ACCEL_DETECT */

    return accel;
}
#endif /* ARCH_ALPHA */

uint32_t a52_detect_accel (uint32_t accel)
{
#if defined (ARCH_X86) || defined (ARCH_PPC) || defined (ARCH_ALPHA) || defined (ARCH_SPARC)
    accel = arch_accel (accel);
#endif
    return accel;
