74:     win_instance_t * instance = (win_instance_t *) _instance;
75:     int current_buffer;
76:     MMRESULT result;
77: 
78: #ifdef LIBA52_DOUBLE
79:     convert_t samples[256 * 2];
80:     int i;
81: 
82:     for (i = 0; i < 256 * 2; i++)
83: 	samples[i] = _samples[i];
84: #else
85:     convert_t * samples = _samples;
86: #endif
87: 
88:     flags &= A52_CHANNEL_MASK | A52_LFE;
89: 
90:     if (instance->set_params) {
91: 	WAVEFORMATEX waveformat;
92: 	MMRESULT result;
93: 	int i;
94: 
95: 	waveformat.wFormatTag = WAVE_FORMAT_PCM;
96: 	waveformat.nChannels = 2;
97: 	waveformat.nSamplesPerSec = instance->sample_rate;
98: 	waveformat.wBitsPerSample = 16;
99: 	waveformat.nBlockAlign = 4;
100: 	waveformat.nAvgBytesPerSec = 4 * instance->sample_rate;
101: 
102: 	result = waveOutOpen (&instance->h_waveout, WAVE_MAPPER, &waveformat,
103: 			      0 /*callback*/, 0 /*data*/, CALLBACK_NULL);
104: 	if (result != MMSYSERR_NOERROR) {
105: 	    fprintf (stderr, "Can not open waveOut device\n");
106: 	    return 1;
107: 	}
108: 
109: 	for (i = 0; i < NUMBUF; i++) {
110: 	    instance->waveheader[i].lpData = (LPSTR)instance->int16_samples[i];
111: 	    instance->waveheader[i].dwBufferLength = 256 * 2 * sizeof(int16_t);
112: 	    instance->waveheader[i].dwFlags = WHDR_DONE;
113: 	}
114: 
115: 	instance->flags = flags;
116: 	instance->set_params = 0;
117:     } else if ((flags == A52_DOLBY) && (instance->flags == A52_STEREO)) {
118: 	fprintf (stderr, "Switching from stereo to dolby surround\n");
119: 	instance->flags = A52_DOLBY;
