126:     current_buffer = instance->current_buffer;
127:     instance->current_buffer = (current_buffer + 1) % NUMBUF;
128: 
129:     while (!(instance->waveheader[current_buffer].dwFlags & WHDR_DONE))
130: 	Sleep (1000 * 256 / instance->sample_rate);
