132:     result = waveOutUnprepareHeader (instance->h_waveout,
133: 				     &instance->waveheader[current_buffer],
134: 				     sizeof(WAVEHDR));
135:     if (result != MMSYSERR_NOERROR) {
136: 	fprintf (stderr, "waveOutUnprepareHeader failed\n");
137: 	return 1;
138:     }
139: 
140:     instance->waveheader[current_buffer].dwFlags = 0;
141:     result = waveOutPrepareHeader (instance->h_waveout,
