76: static inline void ifft2 (complex_t * buf)
77: {
78:     sample_t r, i;
79: 
80:     r = buf[0].real;
81:     i = buf[0].imag;
82:     buf[0].real += buf[1].real;
83:     buf[0].imag += buf[1].imag;
84:     buf[1].real = r - buf[1].real;
85:     buf[1].imag = i - buf[1].imag;
86: }
