88: static inline void ifft4 (complex_t * buf)
89: {
90:     sample_t tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8;
91: 
92:     tmp1 = buf[0].real + buf[1].real;
93:     tmp2 = buf[3].real + buf[2].real;
94:     tmp3 = buf[0].imag + buf[1].imag;
95:     tmp4 = buf[2].imag + buf[3].imag;
96:     tmp5 = buf[0].real - buf[1].real;
97:     tmp6 = buf[0].imag - buf[1].imag;
98:     tmp7 = buf[2].imag - buf[3].imag;
99:     tmp8 = buf[3].real - buf[2].real;
100: 
101:     buf[0].real = tmp1 + tmp2;
102:     buf[0].imag = tmp3 + tmp4;
103:     buf[2].real = tmp1 - tmp2;
104:     buf[2].imag = tmp3 - tmp4;
105:     buf[1].real = tmp5 + tmp7;
106:     buf[1].imag = tmp6 + tmp8;
107:     buf[3].real = tmp5 - tmp7;
108:     buf[3].imag = tmp6 - tmp8;
109: }
110: 
111: /* basic radix-2 ifft butterfly */
112: 
113: #define BUTTERFLY_0(t0,t1,W0,W1,d0,d1) do {	\
114:     t0 = MUL (W1, d1) + MUL (W0, d0);		\
115:     t1 = MUL (W0, d1) - MUL (W1, d0);		\
116: } while (0)
117: 
118: /* radix-2 ifft butterfly with bias */
119: 
120: #define BUTTERFLY_B(t0,t1,W0,W1,d0,d1) do {	\
121:     t0 = BIAS (MUL (d1, W1) + MUL (d0, W0));	\
122:     t1 = BIAS (MUL (d1, W0) - MUL (d0, W1));	\
123: } while (0)
124: 
125: /* the basic split-radix ifft butterfly */
126: 
127: #define BUTTERFLY(a0,a1,a2,a3,wr,wi) do {		\
128:     BUTTERFLY_0 (tmp5, tmp6, wr, wi, a2.real, a2.imag);	\
129:     BUTTERFLY_0 (tmp8, tmp7, wr, wi, a3.imag, a3.real);	\
130:     tmp1 = tmp5 + tmp7;					\
131:     tmp2 = tmp6 + tmp8;					\
132:     tmp3 = tmp6 - tmp8;					\
133:     tmp4 = tmp7 - tmp5;					\
134:     a2.real = a0.real - tmp1;				\
135:     a2.imag = a0.imag - tmp2;				\
136:     a3.real = a1.real - tmp3;				\
137:     a3.imag = a1.imag - tmp4;				\
138:     a0.real += tmp1;					\
139:     a0.imag += tmp2;					\
140:     a1.real += tmp3;					\
141:     a1.imag += tmp4;					\
142: } while (0)
143: 
144: /* split-radix ifft butterfly, specialized for wr=1 wi=0 */
145: 
146: #define BUTTERFLY_ZERO(a0,a1,a2,a3) do {	\
147:     tmp1 = a2.real + a3.real;			\
148:     tmp2 = a2.imag + a3.imag;			\
149:     tmp3 = a2.imag - a3.imag;			\
150:     tmp4 = a3.real - a2.real;			\
151:     a2.real = a0.real - tmp1;			\
152:     a2.imag = a0.imag - tmp2;			\
153:     a3.real = a1.real - tmp3;			\
154:     a3.imag = a1.imag - tmp4;			\
155:     a0.real += tmp1;				\
156:     a0.imag += tmp2;				\
157:     a1.real += tmp3;				\
158:     a1.imag += tmp4;				\
159: } while (0)
160: 
161: /* split-radix ifft butterfly, specialized for wr=wi */
162: 
163: #define BUTTERFLY_HALF(a0,a1,a2,a3,w) do {	\
164:     tmp5 = MUL (a2.real + a2.imag, w);		\
165:     tmp6 = MUL (a2.imag - a2.real, w);		\
166:     tmp7 = MUL (a3.real - a3.imag, w);		\
167:     tmp8 = MUL (a3.imag + a3.real, w);		\
168:     tmp1 = tmp5 + tmp7;				\
169:     tmp2 = tmp6 + tmp8;				\
170:     tmp3 = tmp6 - tmp8;				\
171:     tmp4 = tmp7 - tmp5;				\
172:     a2.real = a0.real - tmp1;			\
173:     a2.imag = a0.imag - tmp2;			\
174:     a3.real = a1.real - tmp3;			\
175:     a3.imag = a1.imag - tmp4;			\
176:     a0.real += tmp1;				\
177:     a0.imag += tmp2;				\
178:     a1.real += tmp3;				\
179:     a1.imag += tmp4;				\
180: } while (0)
