193: static void ifft_pass (complex_t * buf, sample_t * weight, int n)
194: {
195:     complex_t * buf1;
196:     complex_t * buf2;
197:     complex_t * buf3;
198:     sample_t tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8;
199:     int i;
200: 
201:     buf++;
202:     buf1 = buf + n;
203:     buf2 = buf + 2 * n;
204:     buf3 = buf + 3 * n;
205: 
206:     BUTTERFLY_ZERO (buf[-1], buf1[-1], buf2[-1], buf3[-1]);
207: 
208:     i = n - 1;
209: 
210:     do {
211: 	BUTTERFLY (buf[0], buf1[0], buf2[0], buf3[0],
212: 		   weight[0], weight[2*i-n]);
213: 	buf++;
214: 	buf1++;
215: 	buf2++;
216: 	buf3++;
217: 	weight++;
218:     } while (--i);
219: }
