257: void a52_imdct_512 (sample_t * data, sample_t * delay, sample_t bias)
258: {
259:     int i, k;
260:     sample_t t_r, t_i, a_r, a_i, b_r, b_i, w_1, w_2;
261:     const sample_t * window = a52_imdct_window;
262:     complex_t buf[128];
263: 	
264:     for (i = 0; i < 128; i++) {
265: 	k = fftorder[i];
266: 	t_r = pre1[i].real;
267: 	t_i = pre1[i].imag;
268: 	BUTTERFLY_0 (buf[i].real, buf[i].imag, t_r, t_i, data[k], data[255-k]);
269:     }
270: 
271:     ifft128 (buf);
272: 
273:     /* Post IFFT complex multiply plus IFFT complex conjugate*/
274:     /* Window and convert to real valued signal */
275:     for (i = 0; i < 64; i++) {
276: 	/* y[n] = z[n] * (xcos1[n] + j * xsin1[n]) ; */
277: 	t_r = post1[i].real;
278: 	t_i = post1[i].imag;
279: 	BUTTERFLY_0 (a_r, a_i, t_i, t_r, buf[i].imag, buf[i].real);
280: 	BUTTERFLY_0 (b_r, b_i, t_r, t_i, buf[127-i].imag, buf[127-i].real);
281: 
282: 	w_1 = window[2*i];
283: 	w_2 = window[255-2*i];
284: 	BUTTERFLY_B (data[255-2*i], data[2*i], w_2, w_1, a_r, delay[2*i]);
285: 	delay[2*i] = a_i;
286: 
287: 	w_1 = window[2*i+1];
288: 	w_2 = window[254-2*i];
289: 	BUTTERFLY_B (data[2*i+1], data[254-2*i], w_1, w_2, b_r, delay[2*i+1]);
290: 	delay[2*i+1] = b_i;
291:     }
292: }
