294: void a52_imdct_256 (sample_t * data, sample_t * delay, sample_t bias)
295: {
296:     int i, k;
297:     sample_t t_r, t_i, a_r, a_i, b_r, b_i, c_r, c_i, d_r, d_i, w_1, w_2;
298:     const sample_t * window = a52_imdct_window;
299:     complex_t buf1[64], buf2[64];
300: 
301:     /* Pre IFFT complex multiply plus IFFT cmplx conjugate */
302:     for (i = 0; i < 64; i++) {
303: 	k = fftorder[i];
304: 	t_r = pre2[i].real;
305: 	t_i = pre2[i].imag;
306: 	BUTTERFLY_0 (buf1[i].real, buf1[i].imag, t_r, t_i, data[k], data[254-k]);
307: 	BUTTERFLY_0 (buf2[i].real, buf2[i].imag, t_r, t_i, data[k+1], data[255-k]);
308:     }
309: 
310:     ifft64 (buf1);
311:     ifft64 (buf2);
312: 
313:     /* Post IFFT complex multiply */
314:     /* Window and convert to real valued signal */
315:     for (i = 0; i < 32; i++) {
316: 	/* y1[n] = z1[n] * (xcos2[n] + j * xs in2[n]) ; */ 
317: 	t_r = post2[i].real;
318: 	t_i = post2[i].imag;
319: 	BUTTERFLY_0 (a_r, a_i, t_i, t_r, buf1[i].imag, buf1[i].real);
320: 	BUTTERFLY_0 (b_r, b_i, t_r, t_i, buf1[63-i].imag, buf1[63-i].real);
321: 	BUTTERFLY_0 (c_r, c_i, t_i, t_r, buf2[i].imag, buf2[i].real);
322: 	BUTTERFLY_0 (d_r, d_i, t_r, t_i, buf2[63-i].imag, buf2[63-i].real);
323: 
