357: static void mix5to1 (sample_t * samples, sample_t bias)
358: {
359:     int i;
360: 
361:     for (i = 0; i < 256; i++)
362: 	samples[i] += BIAS (samples[i + 256] + samples[i + 512] +
363: 			    samples[i + 768] + samples[i + 1024]);
364: }
