366: static void mix3to2 (sample_t * samples, sample_t bias)
367: {
368:     int i;
369:     sample_t common;
370: 
371:     for (i = 0; i < 256; i++) {
372: 	common = BIAS (samples[i + 256]);
373: 	samples[i] += common;
374: 	samples[i + 256] = samples[i + 512] + common;
375:     }
376: }
