378: static void mix21to2 (sample_t * left, sample_t * right, sample_t bias)
379: {
380:     int i;
381:     sample_t common;
382: 
383:     for (i = 0; i < 256; i++) {
384: 	common = BIAS (right[i + 256]);
385: 	left[i] += common;
386: 	right[i] += common;
387:     }
