390: static void mix21toS (sample_t * samples, sample_t bias)
391: {
392:     int i;
393:     sample_t surround;
394: 
395:     for (i = 0; i < 256; i++) {
396: 	surround = samples[i + 512];
397: 	samples[i] += BIAS (-surround);
398: 	samples[i + 256] += BIAS (surround);
399:     }
400: }
