403: {
404:     int i;
405:     sample_t common;
406: 
407:     for (i = 0; i < 256; i++) {
408: 	common = BIAS (samples[i + 256] + samples[i + 768]);
409: 	samples[i] += common;
410: 	samples[i + 256] = samples[i + 512] + common;
