48: static int solaris_setup (ao_instance_t * _instance, int sample_rate,
49: 			  int * flags, level_t * level, sample_t * bias)
50: {
51:     solaris_instance_t * instance = (solaris_instance_t *) _instance;
52: 
53:     if ((instance->set_params == 0) && (instance->sample_rate != sample_rate))
54: 	return 1;
55:     instance->sample_rate = sample_rate;
56: 
57:     *flags = instance->flags;
58:     *level = CONVERT_LEVEL;
59:     *bias = CONVERT_BIAS;
60: 
61:     return 0;
62: }
63: 
64: static int solaris_play (ao_instance_t * _instance, int flags,
65: 			 sample_t * _samples)
66: {
67:     solaris_instance_t * instance = (solaris_instance_t *) _instance;
68:     int16_t int16_samples[256*2];
69: 
70: #ifdef LIBA52_DOUBLE
71:     convert_t samples[256 * 2];
72:     int i;
73: 
74:     for (i = 0; i < 256 * 2; i++)
75: 	samples[i] = _samples[i];
76: #else
77:     convert_t * samples = _samples;
78: #endif
79: 
80:     if (instance->set_params) {
81: 	audio_info_t info;
82: 
83:         /* Setup our parameters */
84:         AUDIO_INITINFO (&info);
85: 	info.play.sample_rate = instance->sample_rate;
86: 	info.play.precision = 16;
87: 	info.play.channels = 2;
88: 	info.play.encoding = AUDIO_ENCODING_LINEAR;
89: 	
90: 	/* Write our configuration */
91: 	/* An implicit GETINFO is also performed. */
92: 	if (ioctl (instance->fd, AUDIO_SETINFO, &info) < 0) {
93: 	    perror ("Writing audio config block");
94: 	    return 1;
95: 	}
96: 
97: 	if ((info.play.sample_rate != instance->sample_rate) ||
98: 	    (info.play.precision != 16) || (info.play.channels != 2)) {
99: 	    fprintf (stderr, "Wanted %dHz %d bits %d channels\n",
100: 		     instance->sample_rate, 16, 2);
101: 	    fprintf (stderr, "Got    %dHz %d bits %d channels\n",
102: 		     info.play.sample_rate, info.play.precision,
103: 		     info.play.channels);
104: 	    return 1;
105: 	}
106: 
107: 	instance->flags = flags;
108: 	instance->set_params = 0;
109:     } else if ((flags == A52_DOLBY) && (instance->flags == A52_STEREO)) {
110: 	fprintf (stderr, "Switching from stereo to dolby surround\n");
111: 	instance->flags = A52_DOLBY;
112:     } else if ((flags == A52_STEREO) && (instance->flags == A52_DOLBY)) {
113: 	fprintf (stderr, "Switching from dolby surround to stereo\n");
114: 	instance->flags = A52_STEREO;
115:     } else if (flags != instance->flags)
116: 	return 1;
117: 
118:     convert2s16_2 (samples, int16_samples);
119:     write (instance->fd, int16_samples, 256 * sizeof (int16_t) * 2);
120: 
121:     return 0;
122: }
