131: static ao_instance_t * solaris_open (int flags)
132: {
133:     solaris_instance_t * instance;
134: 
135:     instance = malloc (sizeof (solaris_instance_t));
136:     if (instance == NULL)
137: 	return NULL;
138: 
139:     instance->ao.setup = solaris_setup;
140:     instance->ao.play = solaris_play;
141:     instance->ao.close = solaris_close;
142: 
143:     instance->sample_rate = 0;
144:     instance->set_params = 1;
145:     instance->flags = flags;
146: 
147:     instance->fd = open ("/dev/audio", O_WRONLY);
148:     if (instance->fd < 0) {
149: 	fprintf (stderr, "Can not open /dev/audio\n");
150: 	free (instance);
